  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB1LC_0LC1RB_1LA1LD_0RA0RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (8 * j + 4), (cden [] [] j BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
      split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
      rewrite (gso_1RB1LC_0LC1RB_1LA1LD_0RA0RB p j E).
      exact (srun_sound tm true true chb_1RB1LC_0LC1RB_1LA1LD_0RA0RB B0_1RB1LC_0LC1RB_1LA1LD_0RA0RB BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 4
               run_boot_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
