(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma visx_1RB1LC_0LC1RB_1LA1LD_0RA0RB : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LC_0LC1RB_1LA1LD_0RA0RB = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (8 * j + 4), (cden [] [] j BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gso_1RB1LC_0LC1RB_1LA1LD_0RA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RB_1LA1LD_0RA0RB B0_1RB1LC_0LC1RB_1LA1LD_0RA0RB BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 4
             run_boot_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LC1RB_1LA1LD_0RA0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (8 * j + 8), (cden [] [] j BM1_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [| exact (gbo2_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gxi_1RB1LC_0LC1RB_1LA1LD_0RA0RB j).
    exact (srun_sound tm true true chm_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM0_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM1_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 8
             run_shift_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin3 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LC_0LC1RB_1LA1LD_0RA0RB p (pow2 j) (pow2 j));
      [exact HB2|].
    exists (8 * j + 4), (cden [] [] j BM31_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [| exact (gbo3_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gxi2_1RB1LC_0LC1RB_1LA1LD_0RA0RB j).
    exact (srun_sound tm true true chm3_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM30_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM31_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 4
             run_shift3_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB3 as (nB & cB & _ & HcB & HlB).
  apply (vis_via_fill tm Cc Cin3 lapin3_1RB1LC_0LC1RB_1LA1LD_0RA0RB q p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (vis_lift_of_csteps tm (fun _ : positive => Cin3 (fill (pow2 j))) xH).
  apply (vis_of_run tm (fun _ : positive => Cin3 (fill (pow2 j)))
                    true true l BE0_1RB1LC_0LC1RB_1LA1LD_0RA0RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi3_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
Qed.



(** ** The lap *)

