(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC1RB_1LA1LD_0RA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 25.
  assert (H : match csteps tm 25 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 25 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC1RB_1LA1LD_0RA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC1RB_1LA1LD_0RA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC1RB_1LA1LD_0RA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC1RB_1LA1LD_0RA0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LC_0LC1RB_1LA1LD_0RA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC1RB_1LA1LD_0RA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (8 * j + 4), (cden [] [] j BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gso_1RB1LC_0LC1RB_1LA1LD_0RA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RB_1LA1LD_0RA0RB B0_1RB1LC_0LC1RB_1LA1LD_0RA0RB BB1_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 4
             run_boot_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LC1RB_1LA1LD_0RA0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (8 * j + 8), (cden [] [] j BM1_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [| exact (gbo2_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gxi_1RB1LC_0LC1RB_1LA1LD_0RA0RB j).
    exact (srun_sound tm true true chm_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM0_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM1_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 8
             run_shift_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin3 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LC_0LC1RB_1LA1LD_0RA0RB p (pow2 j) (pow2 j));
      [exact HB2|].
    exists (8 * j + 4), (cden [] [] j BM31_1RB1LC_0LC1RB_1LA1LD_0RA0RB).
    split; [| exact (gbo3_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
    rewrite (gxi2_1RB1LC_0LC1RB_1LA1LD_0RA0RB j).
    exact (srun_sound tm true true chm3_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM30_1RB1LC_0LC1RB_1LA1LD_0RA0RB BM31_1RB1LC_0LC1RB_1LA1LD_0RA0RB 8 4
             run_shift3_1RB1LC_0LC1RB_1LA1LD_0RA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB3 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin3 lapin3_1RB1LC_0LC1RB_1LA1LD_0RA0RB t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin3 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin3 (fill (pow2 j)))
                    true true l BE0_1RB1LC_0LC1RB_1LA1LD_0RA0RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi3_1RB1LC_0LC1RB_1LA1LD_0RA0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC1RB_1LA1LD_0RA0RB : forall t, ~ In t pins_1RB1LC_0LC1RB_1LA1LD_0RA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC1RB_1LA1LD_0RA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_0RA0RB (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_0RA0RB [SRotL 1; SWin 1; SCycL 5 0; SWin 4; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_0RA0RB (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_0RA0RB [SRotL 1; SWin 1; SCycL 5 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC1RB_1LA1LD_0RA0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_0RA0RB
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_0RA0RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_0RA0RB [SRotL 1; SWin 1; SCycL 5 0; SWin 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_0RA0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_0RA0RB (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_0RA0RB [SRotL 1; SWin 1; SCycL 5 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_0RA0RB
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LC_0LC1RB_1LA1LD_0RA0RB : NeverQuasiHaltsTr tm_1RB1LC_0LC1RB_1LA1LD_0RA0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_0LC1RB_1LA1LD_0RA0RB pins_1RB1LC_0LC1RB_1LA1LD_0RA0RB Cc 2).
  - exact boot_1RB1LC_0LC1RB_1LA1LD_0RA0RB.
  - intros p _. apply lap_1RB1LC_0LC1RB_1LA1LD_0RA0RB.
  - intros t Ht p _. apply fire_1RB1LC_0LC1RB_1LA1LD_0RA0RB. exact Ht.
Qed.

Theorem nonhalt_1RB1LC_0LC1RB_1LA1LD_0RA0RB : NonHalt tm_1RB1LC_0LC1RB_1LA1LD_0RA0RB.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1LC_0LC1RB_1LA1LD_0RA0RB. Qed.

