(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC1RB_1LA1LD_1LA0RB : forall t, ~ In t pins_1RB1LC_0LC1RB_1LA1LD_1LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC1RB_1LA1LD_1LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_1LA0RB (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_1LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_1LA0RB (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_1LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC1RB_1LA1LD_1LA0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_1LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_1LA0RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_1LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_1LA0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RB_1LA1LD_1LA0RB (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RB_1LA1LD_1LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LC_0LC1RB_1LA1LD_1LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LC_0LC1RB_1LA1LD_1LA0RB : NeverQuasiHaltsTr tm_1RB1LC_0LC1RB_1LA1LD_1LA0RB.
Proof.
