(** ** The lap *)

Lemma lap_1RB1LC_0LC1RB_1LD0RB_1LA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LC1RB_1LD0RB_1LA1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_0LC1RB_1LD0RB_1LA1LA B0_1RB1LC_0LC1RB_1LD0RB_1LA1LA B1_1RB1LC_0LC1RB_1LD0RB_1LA1LA 6 14 p j' [] []).
    + exact run_ovf_1RB1LC_0LC1RB_1LD0RB_1LA1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LC1RB_1LD0RB_1LA1LA p j' E).
    + exact (geo_1RB1LC_0LC1RB_1LD0RB_1LA1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC1RB_1LD0RB_1LA1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

