Lemma gsi_1RB1LC_0LC1RB_1RB1LD_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A0_1RB1LC_0LC1RB_1RB1LD_1LA0RB.
