(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC1RB_1RB1LD_1LA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC1RB_1RB1LD_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC1RB_1RB1LD_1LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC1RB_1RB1LD_1LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC1RB_1RB1LD_1LA0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LC_0LC1RB_1RB1LD_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC1RB_1RB1LD_1LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 6), (cden [] [] j BB1_1RB1LC_0LC1RB_1RB1LD_1LA0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RB_1RB1LD_1LA0RB j)].
    rewrite (gso_1RB1LC_0LC1RB_1RB1LD_1LA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RB_1RB1LD_1LA0RB B0_1RB1LC_0LC1RB_1RB1LD_1LA0RB BB1_1RB1LC_0LC1RB_1RB1LD_1LA0RB 6 6
             run_boot_1RB1LC_0LC1RB_1RB1LD_1LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LC1RB_1RB1LD_1LA0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_1RB1LC_0LC1RB_1RB1LD_1LA0RB).
    split; [| exact (gbo2_1RB1LC_0LC1RB_1RB1LD_1LA0RB j)].
    rewrite (gxi_1RB1LC_0LC1RB_1RB1LD_1LA0RB j).
    exact (srun_sound tm true true chm_1RB1LC_0LC1RB_1RB1LD_1LA0RB BM0_1RB1LC_0LC1RB_1RB1LD_1LA0RB BM1_1RB1LC_0LC1RB_1RB1LD_1LA0RB 6 4
             run_shift_1RB1LC_0LC1RB_1RB1LD_1LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB1LC_0LC1RB_1RB1LD_1LA0RB t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1LC_0LC1RB_1RB1LD_1LA0RB xH j [] []);
