Lemma gsi_1RB1LC_0LC1RD_0RB1LA_0LC0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LC_0LC1RD_0RB1LA_0LC0RA.
