(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LC1RD_0RB1LA_0LC0RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LC1RD_0RB1LA_0LC0RA p (pow2 j)).
  - exists (6 * j + 9), (cden [] [] j BB1_1RB1LC_0LC1RD_0RB1LA_0LC0RA).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RD_0RB1LA_0LC0RA j)].
    rewrite (gso_1RB1LC_0LC1RD_0RB1LA_0LC0RA p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RD_0RB1LA_0LC0RA B0_1RB1LC_0LC1RD_0RB1LA_0LC0RA BB1_1RB1LC_0LC1RD_0RB1LA_0LC0RA 6 9
