Lemma gsi_1RB1LC_0LC1RD_1LA0RB_0LA1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB1LC_0LC1RD_1LA0RB_0LA1RB.
Proof.
