(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LC1RD_1LA0RB_1RB0LB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LC1RD_1LA0RB_1RB0LB p (pow2 j)).
  - exists (6 * j + 6), (cden [] [] j BB1_1RB1LC_0LC1RD_1LA0RB_1RB0LB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC1RD_1LA0RB_1RB0LB j)].
    rewrite (gso_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RD_1LA0RB_1RB0LB B0_1RB1LC_0LC1RD_1LA0RB_1RB0LB BB1_1RB1LC_0LC1RD_1LA0RB_1RB0LB 6 6
             run_boot_1RB1LC_0LC1RD_1LA0RB_1RB0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 17), (cden [] [] j B1_1RB1LC_0LC1RD_1LA0RB_1RB0LB).
    split; [| exact (geo_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j E)].
    rewrite (gxi_1RB1LC_0LC1RD_1LA0RB_1RB0LB j).
    exact (srun_sound tm true true che_1RB1LC_0LC1RD_1LA0RB_1RB0LB BE0_1RB1LC_0LC1RD_1LA0RB_1RB0LB B1_1RB1LC_0LC1RD_1LA0RB_1RB0LB 6 17
             run_exit_1RB1LC_0LC1RD_1LA0RB_1RB0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_0LC1RD_1LA0RB_1RB0LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC1RD_1LA0RB_1RB0LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 11.
  assert (H : match csteps tm 11 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC1RD_1LA0RB_1RB0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LC1RD_1LA0RB_1RB0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC1RD_1LA0RB_1RB0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC1RD_1LA0RB_1RB0LB t p (pow2 j)).
  - exists (6 * j + 6), (cden [] [] j BB1_1RB1LC_0LC1RD_1LA0RB_1RB0LB). split;
      [| exact (gbo_1RB1LC_0LC1RD_1LA0RB_1RB0LB j)].
    rewrite (gso_1RB1LC_0LC1RD_1LA0RB_1RB0LB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC1RD_1LA0RB_1RB0LB B0_1RB1LC_0LC1RD_1LA0RB_1RB0LB BB1_1RB1LC_0LC1RD_1LA0RB_1RB0LB 6 6
             run_boot_1RB1LC_0LC1RD_1LA0RB_1RB0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC1RD_1LA0RB_1RB0LB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LC1RD_1LA0RB_1RB0LB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC1RD_1LA0RB_1RB0LB : forall t, ~ In t pins_1RB1LC_0LC1RD_1LA0RB_1RB0LB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC1RD_1LA0RB_1RB0LB.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC1RD_1LA0RB_1RB0LB (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SWinR 4; SCycL 2 0; SWin 1; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 6; SCycR 4; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 6] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1LA0RB_1RB0LB [SCycL 2 0; SWin 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LC_0LC1RD_1LA0RB_1RB0LB : NeverQuasiHaltsTr tm_1RB1LC_0LC1RD_1LA0RB_1RB0LB.
