(** 1RB1LC_0LC1RD_1LA0RB_1RB1RB *)
Definition tm_1RB1LC_0LC1RD_1LA0RB_1RB1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
