(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LC_1LA0RD_1LA0RB_0LB1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB1LC_1LA0RD_1LA0RB_0LB1RA /\
  lift (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB1LC_1LA0RD_1LA0RB_0LB1RA) = lift (Cc (Pos.succ p)).
Proof.
