(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_1LA0RD_1RB1LB_0LC1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB1LC_1LA0RD_1RB1LB_0LC1RD p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 8), (cden [] [] j BB1_1RB1LC_1LA0RD_1RB1LB_0LC1RD).
      split; [lia|]. split; [| exact (gbo_1RB1LC_1LA0RD_1RB1LB_0LC1RD j)].
      rewrite (gso_1RB1LC_1LA0RD_1RB1LB_0LC1RD p j E).
      exact (srun_sound tm true true chb_1RB1LC_1LA0RD_1RB1LB_0LC1RD B0_1RB1LC_1LA0RD_1RB1LB_0LC1RD BB1_1RB1LC_1LA0RD_1RB1LB_0LC1RD 6 8
               run_boot_1RB1LC_1LA0RD_1RB1LB_0LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_1LA0RD_1RB1LB_0LC1RD p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 4), (cden [] [] j BM1_1RB1LC_1LA0RD_1RB1LB_0LC1RD).
      split; [| exact (gbo2_1RB1LC_1LA0RD_1RB1LB_0LC1RD j)].
      rewrite (gxi_1RB1LC_1LA0RD_1RB1LB_0LC1RD j).
      exact (srun_sound tm true true chm_1RB1LC_1LA0RD_1RB1LB_0LC1RD BM0_1RB1LC_1LA0RD_1RB1LB_0LC1RD BM1_1RB1LC_1LA0RD_1RB1LB_0LC1RD 6 4
               run_shift_1RB1LC_1LA0RD_1RB1LB_0LC1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin3 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LC_1LA0RD_1RB1LB_0LC1RD p (pow2 j) (pow2 j));
        [exact HB2|].
      exists (6 * j + 6), (cden [] [] j BM31_1RB1LC_1LA0RD_1RB1LB_0LC1RD).
