(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_1LA0RD_1RD1LA_0LB1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LC_1LA0RD_1RD1LA_0LB1RB. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_1LA0RD_1RD1LA_0LB1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_1LA0RD_1RD1LA_0LB1RB p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB1LC_1LA0RD_1RD1LA_0LB1RB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_1LA0RD_1RD1LA_0LB1RB j)].
    rewrite (gso_1RB1LC_1LA0RD_1RD1LA_0LB1RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_1LA0RD_1RD1LA_0LB1RB B0_1RB1LC_1LA0RD_1RD1LA_0LB1RB BB1_1RB1LC_1LA0RD_1RD1LA_0LB1RB 4 6
             run_boot_1RB1LC_1LA0RD_1RD1LA_0LB1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 8), (cden [] [] j B1_1RB1LC_1LA0RD_1RD1LA_0LB1RB).
    split; [| exact (geo_1RB1LC_1LA0RD_1RD1LA_0LB1RB p j E)].
    rewrite (gxi_1RB1LC_1LA0RD_1RD1LA_0LB1RB j).
    exact (srun_sound tm true true che_1RB1LC_1LA0RD_1RD1LA_0LB1RB BE0_1RB1LC_1LA0RD_1RD1LA_0LB1RB B1_1RB1LC_1LA0RD_1RD1LA_0LB1RB 4 8
             run_exit_1RB1LC_1LA0RD_1RD1LA_0LB1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_1LA0RD_1RD1LA_0LB1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_1LA0RD_1RD1LA_0LB1RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_1LA0RD_1RD1LA_0LB1RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_1LA0RD_1RD1LA_0LB1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_1LA0RD_1RD1LA_0LB1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_1LA0RD_1RD1LA_0LB1RB = Some t ->
  forall p j, cview p = (S j, None) ->
