Lemma fireo_1RB1LC_1LA0RD_1RD1LA_0LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_1LA0RD_1RD1LA_0LD1RB = Some t ->
