Lemma geo_1RB1LC_1LA1LC_0RD0LA_1LB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1LC_0RD0LA_1LB1RD) = lift (Cc (Pos.succ p)).
