  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_1LA1LC_0RD0LA_1LB1RD
             = (StD, (rep [S1;S0] (S j) ++ [S1;S1], S1, ([S1]) ++ [S0]))).
  { unfold cden, B1_1RB1LC_1LA1LC_0RD0LA_1LB1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
