  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S1, [S1]))).
  { unfold Cc_1RB1LC_1LA1LC_0RD0LA_1LB1RD. rewrite H2.
