    apply (lap_of_run tm Cc true true cho_1RB1LC_1LA1LC_1LB0RD_0LA1RD B0_1RB1LC_1LA1LC_1LB0RD_0LA1RD B1_1RB1LC_1LA1LC_1LB0RD_0LA1RD 4 10 p j' [] []).
