(** ** The lap *)

Lemma lap_1RB1LC_1LA1RB_0LD0LA_0RD1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
