    apply (lap_of_run tm Cc true true cho_1RB1LC_1LA1RB_0LD0LD_0RA1LC B0_1RB1LC_1LA1RB_0LD0LD_0RA1LC B1_1RB1LC_1LA1RB_0LD0LD_0RA1LC 4 9 p j' [] []).
