(** 1RB1LC_1LA1RB_0RB0LD_0RB1LC *)
(** 1RB1LC_1LA1RB_0RB0LD_0RB1LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LC_1LA1RB_0RB0LD_0RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S1 DL StC end.

(** Its mirror 1LB1RC_1RA1LB_0LB0RD_0LB1RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LC_1LA1RB_0RB0LD_0RB1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LC_1LA1RB_0RB0LD_0RB1LC : list Instr := [].
Definition tmw_1RB1LC_1LA1RB_0RB0LD_0RB1LC : TM := tm_wrap_trs tmm_1RB1LC_1LA1RB_0RB0LD_0RB1LC pins_1RB1LC_1LA1RB_0RB0LD_0RB1LC.
