Lemma mirror_ok_1RB1LC_1LA1RB_0RB0LD_0RB1LC : mirror_tm tm_1RB1LC_1LA1RB_0RB0LD_0RB1LC = tmm_1RB1LC_1LA1RB_0RB0LD_0RB1LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LC_1LA1RB_0RB0LD_0RB1LC (p : positive) : cconf := (StB, (Ap_Alph_10_11_11 p ++ [S0], S1, [S1])).
