(** ** The certificate *)

Definition A0_1RB1LC_1LA1RB_0RB0LD_0RB1LC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S1 (mkS [S1] [] 0 0 []).
