(** 1RB1LC_1LA1RB_0RB0LD_1RA1LC *)
(** 1RB1LC_1LA1RB_0RB0LD_1RA1LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LC_1LA1RB_0RB0LD_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StC end.

(** Its mirror 1LB1RC_1RA1LB_0LB0RD_1LA1RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LC_1LA1RB_0RB0LD_1RA1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list Instr := [].
Definition tmw_1RB1LC_1LA1RB_0RB0LD_1RA1LC : TM := tm_wrap_trs tmm_1RB1LC_1LA1RB_0RB0LD_1RA1LC pins_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Local Notation tm := tmw_1RB1LC_1LA1RB_0RB0LD_1RA1LC.

Lemma mirror_ok_1RB1LC_1LA1RB_0RB0LD_1RA1LC : mirror_tm tm_1RB1LC_1LA1RB_0RB0LD_1RA1LC = tmm_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC (p : positive) : cconf := (StC, (Ap_Alph_10_11_11 p ++ [S1;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SWin 4].

Lemma run_z_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm false true chz_1RB1LC_1LA1RB_0RB0LD_1RA1LC Z0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (Z1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm false true chp_1RB1LC_1LA1RB_0RB0LD_1RA1LC P0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (P1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [] [S1;S0] 1 2 [S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StC *)
Definition Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC (v : positive) : cconf := (StC, (Ip v ++ [S0;S1;S1], S0, [])).
Local Notation Cin := Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap, SPLIT: the carry sweep's period sits one cell
    into the unit, so i = 0 is one concrete window and i = S i' runs with a
    unit PEELED into the prefix (count i' = i - 1) -- the interior-lap
    mirror of the outer j = 0 split. *)
Definition AIZ0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chnz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SWin 4].

Lemma run_innerz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm false true chnz_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIZ0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

Definition AIP0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chnp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_innerp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm false true chnp_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIP0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** The OFFSET start: [E (2^(n+2)+2)] is fixed digit blocks, then the rep.
    Its block count is one short of the outer index, which is why [lapo_]
    below REINDEXES at [j = S j']. *)
Lemma epre_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall n, Ip (xO (xI (pow2 n))) = [S1;S0;S1;S1] ++ rep [S1;S0] n ++ [S1].
Proof.
  intro n. cbn [Ip]. rewrite epow2_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
  cbn [app]. rewrite <- ?app_assoc. cbn [app]. reflexivity.
Qed.

(** Rotating one fixed cell across a rep -- the bridge between a chain's
    natural landing frame and the encoding's block frame ([WTape.rep_rot],
    with the trailing cell fused into the tail). *)
Lemma rrc_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall (x : Sym) (u : list Sym) k (Y : list Sym),
  rep (x :: u) k ++ x :: Y = x :: rep (u ++ [x]) k ++ Y.
Proof.
  intros. change (x :: Y) with ([x] ++ Y). rewrite app_assoc, <- rep_rot.
  cbn [app]. rewrite <- ?app_assoc. reflexivity.
Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1;S0;S1;S1] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2; SRotL 1; SWin 1; SRotL 1; SWin 4; SWinR 1].

Lemma run_boot_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm true true chb_1RB1LC_1LA1RB_0RB0LD_1RA1LC B0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (BB1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 4, 21).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LC_1LA1RB_0RB0LD_1RA1LC : sconf := mkC StC (mkS [S1] [S1;S1] 1 1 [S1;S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LC_1LA1RB_0RB0LD_1RA1LC : list lstep := [SWin 1; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1LC_1LA1RB_0RB0LD_1RA1LC : srun tm true true che_1RB1LC_1LA1RB_0RB0LD_1RA1LC BE0_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Some (B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0 Z0_1RB1LC_1LA1RB_0RB0LD_1RA1LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0 Z1_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, Z0_1RB1LC_1LA1RB_0RB0LD_1RA1LC, Z1_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j P0_1RB1LC_1LA1RB_0RB0LD_1RA1LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j P1_1RB1LC_1LA1RB_0RB0LD_1RA1LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, P0_1RB1LC_1LA1RB_0RB0LD_1RA1LC, P1_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LC_1LA1RB_0RB0LD_1RA1LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LC_1LA1RB_0RB0LD_1RA1LC Z0_1RB1LC_1LA1RB_0RB0LD_1RA1LC Z1_1RB1LC_1LA1RB_0RB0LD_1RA1LC 0 4
               run_z_1RB1LC_1LA1RB_0RB0LD_1RA1LC (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LC_1LA1RB_0RB0LD_1RA1LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LC_1LA1RB_0RB0LD_1RA1LC P0_1RB1LC_1LA1RB_0RB0LD_1RA1LC P1_1RB1LC_1LA1RB_0RB0LD_1RA1LC 4 8
               run_p_1RB1LC_1LA1RB_0RB0LD_1RA1LC (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall p j, cview p = (S (S j), None) ->
  Cc p = cden [] [] j B0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (H1 & _).
  unfold Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, B0_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with ((S j)) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall p j, cview p = (S (S j), None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC
             = (StC, (rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 2) with (S (S j)) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LC_1LA1RB_0RB0LD_1RA1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LC_1LA1RB_0RB0LD_1RA1LC. reflexivity.
Qed.

Lemma gsnz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall v q0, cview v = (0%nat, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Proof.
  intros v q0 E. destruct (ILCounter.cview_some_I v 0 q0 E) as (H1 & _).
  unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, AIZ0_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  rewrite H1. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma genz_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall v q0, cview v = (0%nat, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v q0 E. destruct (ILCounter.cview_some_I v 0 q0 E) as (_ & H2).
  unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ reflexivity
        | cbn [rep app]; rewrite <- ?app_assoc; cbn [app];
          rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gsnp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall v i q0, cview v = (S i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] i AIP0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v (S i) q0 E) as (H1 & _).
  unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, AIP0_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma genp_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall v i q0, cview v = (S i, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] i AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v (S i) q0 E) as (_ & H2).
  unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H2. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma lapin_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct i as [|i'].
  - exists (0 * 0 + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC).
    split; [lia|]. split; [| exact (genz_1RB1LC_1LA1RB_0RB0LD_1RA1LC v q0 E)].
    rewrite (gsnz_1RB1LC_1LA1RB_0RB0LD_1RA1LC v q0 E).
    exact (srun_sound tm false true chnz_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIZ0_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIZ1_1RB1LC_1LA1RB_0RB0LD_1RA1LC 0 4
             run_innerz_1RB1LC_1LA1RB_0RB0LD_1RA1LC (Ip q0 ++ [S0;S1;S1]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - exists (4 * i' + 8), (cden (Ip q0 ++ [S0;S1;S1]) [] i' AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC).
    split; [lia|]. split; [| exact (genp_1RB1LC_1LA1RB_0RB0LD_1RA1LC v i' q0 E)].
    rewrite (gsnp_1RB1LC_1LA1RB_0RB0LD_1RA1LC v i' q0 E).
    exact (srun_sound tm false true chnp_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIP0_1RB1LC_1LA1RB_0RB0LD_1RA1LC AIP1_1RB1LC_1LA1RB_0RB0LD_1RA1LC 4 8
             run_innerp_1RB1LC_1LA1RB_0RB0LD_1RA1LC (Ip q0 ++ [S0;S1;S1]) [] i'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall j, lift (cden [] [] j BB1_1RB1LC_1LA1RB_0RB0LD_1RA1LC) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LC_1LA1RB_0RB0LD_1RA1LC = (StC, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LC_1LA1RB_0RB0LD_1RA1LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StC, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC. rewrite epre_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    first [ rewrite <- ?app_assoc; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  (* The offset boot can land one written blank past the anchor on EITHER
     side, and [lift] sees neither.  Strip it FIRST: [cbn [app]] flattens
     `w ++ [S0]` into one literal and destroys the shape
     [WTape.lift_app_blank_l] matches on. *)
  rewrite HD, HC. rewrite ?lift_app_blank_l.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?lbl_1RB1LC_1LA1RB_0RB0LD_1RA1LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** The exit chain starts from the REPHASED fill (one unit cell rotated out
    front); [rrc_] bridges it back to the encoding's block frame. *)
Lemma gxi_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall j, Cin (fill (xO (xI (pow2 j)))) = cden [] [] j BE0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
Proof.
  intro j.
  assert (Hf : fill (xO (xI (pow2 j))) = fill (pow2 (S (S j))))
    by (cbn [pow2 fill]; reflexivity).
  rewrite Hf.
  destruct (ILCounter.cview_none_I (fill (pow2 (S (S j)))) (S (S j))
              (cview_fill_pow2 (S (S j)))) as (H1 & _).
  unfold Cin_1RB1LC_1LA1RB_0RB0LD_1RA1LC, cden, BE0_1RB1LC_1LA1RB_0RB0LD_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with (S j) by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite (rrc_1RB1LC_1LA1RB_0RB0LD_1RA1LC S1 [S1] (S j)).
  cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
  reflexivity.
Qed.

