(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_1LA1RB_0RB0LD_1RA1LC : forall t, ~ In t pins_1RB1LC_1LA1RB_0RB0LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_A0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_A1_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 5] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_B1_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_C1_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 6] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_D0_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)).
    intros p1 j1 E1. destruct j1 as [|j1'].
    + rewrite (cview_none_shape p1 0 E1).
      exact firez_D1_1RB1LC_1LA1RB_0RB0LD_1RA1LC.
    + exact (fireo_1RB1LC_1LA1RB_0RB0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 7] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
Qed.

