    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_1LA1RB_0RB1LD_0RA0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 5]).
    vm_compute; reflexivity.
