    exact (srun_sound tm true true che_1RB1LC_1LA1RB_0RC0LD_0RA1LC BE0_1RB1LC_1LA1RB_0RC0LD_0RA1LC B1_1RB1LC_1LA1RB_0RC0LD_0RA1LC 4 7
             run_exit_1RB1LC_1LA1RB_0RC0LD_0RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_1LA1RB_0RC0LD_0RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_1LA1RB_0RC0LD_0RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_1LA1RB_0RC0LD_0RA1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_1LA1RB_0RC0LD_0RA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_1LA1RB_0RC0LD_0RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_1LA1RB_0RC0LD_0RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
