Lemma lbl_1RB1LC_1LA1RB_0RC1RD_1RA0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LC_1LA1RB_0RC1RD_1RA0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1RB_0RC1RD_1RA0LA) = lift (Cc (Pos.succ p)).
