Lemma geo_1RB1LC_1LA1RB_0RD0LA_1RB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_1LA1RB_0RD0LA_1RB1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_01_11_011.cview_none_Alph_01_11_011 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_1LA1RB_0RD0LA_1RB1RD
