  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_1LA1RB_0RD0LA_1RB1RD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_1LA1RB_0RD0LA_1RB1RD [SWin 3; SWinR 5; SCycL 2 0; SWin 4; SWinL 6; SCycR 2; SWin 4] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
