    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_1LA1RB_1LA0RD_0LC1RD [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWinR 2; SRotL 1; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_1LA1RB_1LA0RD_0LC1RD [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWinR 2; SRotL 1; SWin 3; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
